const content={leaduno:['LeadUno / sales quality control',`<h2>From conversations to a working process.</h2><p>My own product for AI-assisted quality control of sales conversations. CRM and chat integrations feed a workspace for managers and sellers, with analysis, review and follow-up workflows.</p><p>Python · FastAPI · SQLAlchemy · PostgreSQL · OpenAI API · JavaScript · Chrome extension.</p><p>The work spans product scenarios, backend, interfaces, integrations and operations. Public demo content is synthetic.</p><p><a href="https://leaduno.tech" target="_blank" rel="noreferrer">Visit LeadUno</a></p>`],spread:['Spread Checker / own project',`<h2>A tool that lives beside the market.</h2><p>My own Chrome extension and backend for spread monitoring. The project includes Telegram-linked access, subscriptions, promo codes and referral flows.</p><p>Chrome MV3 · JavaScript · TypeScript · Fastify · Prisma · PostgreSQL.</p><p>Some authentication and payment flows are MVP implementations. This portfolio does not imply audited trading infrastructure or profitability.</p>`],pedagogium:['Pedagogium / research automation',`<h2>Less manual searching. More useful data.</h2><p>Built a course-provider discovery tool for Pedagogium: SERP search, contact extraction, filtering, deduplication, Google Sheets export and Telegram administration with request limits.</p><p>A second project is a Telegram AI-assistant MVP for grant discovery, criteria-based evaluation and contextual discussion.</p><p>Python · external APIs · Google Sheets · Telegram · AI integrations. Related university work includes the ZPSB grant-assistant MVP.</p>`],hools:['HoolsOnline / inherited systems',`<h2>Into the legacy jungle.</h2><p>A six-week Tech Lead engagement on an existing game. I reworked substantial parts of the system, fixed bugs and addressed exploitable game mechanics.</p><p>The project contains Node.js/Express, SQLite legacy systems, a PostgreSQL platform, transactional commands, payment workflows and operational tooling.</p><p>I joined an existing product; I did not create the original game. Specific technical contributions can be discussed in a project walkthrough.</p>`],ascii:['ASCII Cam / strange little experiments',`<h2>Your camera, one character at a time.</h2><p>A Python experiment that turns webcam frames into ASCII. Hand gestures control palettes and character scale, with an optional virtual-camera output.</p><p>Python · OpenCV · NumPy · hand tracking · pyvirtualcam.</p><p>A playful intersection of image processing, interaction and the kind of idea you build because you want it to exist.</p>`],nomis:['Content / community / education',`<h2>Software needs people, too.</h2><p>About nine months as SMM + Marketing Lead helper at NOMIS Reputation Protocol. Content plans, channel-specific voice, articles, community communication, influencer outreach and campaign operations.</p><p>Helped adapt communication for a new TON audience and raised the need for a clearer roadmap. Worked with the Marketing Lead on community and partnership programs.</p><p>Paid work for individual NEAR / Aurora ambassadors included English and Russian guides and coding contests: tasks, code, participant coordination and solution reviews.</p>`],about:['about / human.exe',`<h2>Hi. I like making things work.</h2><p>I'm Yaroslav, also known as yosStudent. My work sits between backend development, AI integrations, automation and product building.</p><p>I've built my own tools, worked on university research automation, spent time untangling an existing game, and helped technical communities understand complicated products.</p><p>I'm finishing Informatyka — Systemy chmurowe at ZPSB, currently in the final semester. Expected graduation: February–March 2027.</p><p>I work comfortably in English and Polish, and create content in Russian too.</p>`],contact:['contact / let’s talk',`<h2>Have something worth building?</h2><p>I'm interested in backend, AI integrations and product engineering opportunities, including work that connects software with technical education.</p><p>Find me through my GitHub profile:</p><p><a href="https://github.com/yosStudent" target="_blank" rel="noreferrer">github.com/yosStudent</a></p><p>Email: <a href="mailto:superplaery@gmail.com">superplaery@gmail.com</a><br>Telegram: <a href="https://t.me/yosexain" target="_blank" rel="noreferrer">@yosexain</a></p>`]};
const modal=document.querySelector('#modal');document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>{const [title,body]=content[b.dataset.open];document.querySelector('#modal-title').textContent=title;document.querySelector('#modal-body').innerHTML=body;modal.showModal()}));document.querySelector('#close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});document.querySelector('#year').textContent=new Date().getFullYear();function clock(){document.querySelector('#clock').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Warsaw',hour:'2-digit',minute:'2-digit'}).format(new Date())+' / WARSAW'}clock();setInterval(clock,60000);
let quiet=matchMedia('(prefers-reduced-motion: reduce)').matches;const q=document.querySelector('#quiet');function motion(){document.body.classList.toggle('quiet',quiet);q.textContent='motion: '+(quiet?'off':'on');q.setAttribute('aria-pressed',String(quiet))}q.onclick=()=>{quiet=!quiet;motion()};motion();
let star=false;try{star=localStorage.getItem('yos-star')==='yes'}catch{}function starUI(){document.querySelector('#star').textContent=star?'★ a star from you':'☆ leave a star';document.querySelector('#star').setAttribute('aria-pressed',String(star))}starUI();document.querySelector('#star').onclick=()=>{star=!star;try{localStorage.setItem('yos-star',star?'yes':'no')}catch{}starUI()};let fi=0;const fortunes=['ideas are cheap.\nship the weird one.','a bug is a side quest\nyou didn’t choose.','build something useful.\nthen make it yours.','one more commit.\nthen actually go to bed.'];document.querySelector('#fortune').onclick=()=>{document.querySelector('#fortune span').textContent=fortunes[++fi%fortunes.length]};
document.querySelector('#resume').onclick=()=>{const text=`YAROSLAV / yosStudent\nBackend, AI integrations & product engineering\n\nPROJECTS\nLeadUno — own AI-assisted sales quality-control product. Python, FastAPI, PostgreSQL, CRM/chat integrations.\nSpread Checker — own Chrome extension + TypeScript/Fastify/Prisma backend.\nPedagogium — course-provider discovery automation and grant-assistant MVP.\nHoolsOnline — six-week Tech Lead engagement on an existing game; system rework, bugs and abuse fixes.\nASCII Cam — gesture-controlled webcam-to-ASCII experiment.\n\nOTHER EXPERIENCE\nNOMIS Reputation Protocol — SMM + Marketing Lead helper, about nine months.\nPaid educational content and coding contests for individual NEAR/Aurora ambassadors.\n\nEDUCATION\nZPSB — Informatyka, Systemy chmurowe. Final semester. Expected graduation Feb–Mar 2027.\n\nLANGUAGES\nEnglish, Polish, Russian.\n\nCONTACT\nsuperplaery@gmail.com\nTelegram: @yosexain — https://t.me/yosexain\nhttps://github.com/yosStudent\nhttps://leaduno.tech\n`;const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='Yaroslav-resume.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
let seed=1234;function rand(){seed=(seed*16807)%2147483647;return seed/2147483647}const sky=document.querySelector('#sky'),sc=sky.getContext('2d');function stars(){sky.width=innerWidth;sky.height=innerHeight;sc.clearRect(0,0,sky.width,sky.height);seed=61;for(let i=0;i<150;i++){let x=rand()*sky.width,y=rand()*sky.height;sc.fillStyle=i%5?'#58697c':'#b0bd97';sc.fillRect(x,y,i%5?1:2,i%5?1:2)}}stars();addEventListener('resize',stars);
const canvas=document.querySelector('#city'),ctx=canvas.getContext('2d');canvas.width=700;canvas.height=210;let lit=false;function city(t=0){seed=317;const w=700,h=210;ctx.fillStyle='#111c30';ctx.fillRect(0,0,w,h);for(let i=0;i<80;i++){ctx.fillStyle=i%4?'#57647d':'#adc3af';ctx.fillRect(rand()*w,rand()*140,1,1)}ctx.fillStyle='#d0d8b3';ctx.fillRect(512,25,22,22);ctx.fillStyle='#111c30';ctx.fillRect(506,20,20,20);for(let row=0;row<3;row++){for(let x=-10;x<w;){const bw=20+Math.floor(rand()*36),bh=20+Math.floor(rand()*(45+row*25));ctx.fillStyle=['#1b2940','#203149','#12202e'][row];ctx.fillRect(x,210-bh,bw,bh);for(let wx=x+5;wx<x+bw-4;wx+=8)for(let wy=215-bh;wy<200;wy+=10){const r=rand();ctx.fillStyle=r>(lit?.35:.7)?(r>.85?'#beb483':'#698d87'):'#263447';ctx.fillRect(wx,wy,3,4)}x+=bw+4}}ctx.fillStyle='#0b1520';ctx.fillRect(0,192,700,18);ctx.fillRect(40,130,4,70);ctx.fillRect(25,129,32,3);ctx.fillStyle='#adbe91';ctx.fillRect(31,133,18,3);ctx.fillStyle='#354d48';for(let x=0;x<700;x+=6)ctx.fillRect(x,194,3,1);ctx.fillStyle='#c7b8de';let sx=quiet?250:((t/30)%850)-50;ctx.fillRect(sx,20,3,1);ctx.fillStyle='#756c8e';ctx.fillRect(sx-8,20,7,1)}let lastCityFrame=0;function frame(t){if(!document.hidden&&t-lastCityFrame>(quiet?1000:60)){city(t);lastCityFrame=t}requestAnimationFrame(frame)}requestAnimationFrame(frame);document.querySelector('#lights').onclick=()=>{lit=!lit;document.querySelector('#lights').textContent=lit?'let the city sleep':'turn on a few more lights'};
