const gallery=[{src:'assets/leaduno-demo.jpg',name:'LeadUno / QC demo',caption:'Actual capture of the public demo, opened locally with neutral Demo A–E labels. All conversations and metrics are synthetic.'},{src:'assets/leaduno-seller.jpg',name:'LeadUno / seller workspace',caption:'Actual capture of the public seller demo with neutral Demo A–E labels. This is not an employee account.'},{src:'assets/spread-panel.jpg',name:'Spread Checker / local panel',caption:'Actual project HTML/CSS opened locally. No account connected, no live market data. The extension runtime is not active in this capture.'}];
let gi=0;function openGallery(i){gi=(i+gallery.length)%gallery.length;const item=gallery[gi];modal.classList.add('gallery-mode');document.querySelector('#modal-title').textContent=item.name;const wrap=document.querySelector('#modal-body');wrap.replaceChildren();const img=document.createElement('img');img.className='gallery-image';img.src=item.src;img.alt=item.name;const cap=document.createElement('p');cap.textContent=item.caption;const controls=document.createElement('div');controls.className='gallery-controls';const prev=document.createElement('button');prev.textContent='previous';prev.onclick=()=>openGallery(gi-1);const next=document.createElement('button');next.textContent='next';next.onclick=()=>openGallery(gi+1);const count=document.createElement('span');count.textContent=`${gi+1} / ${gallery.length}`;controls.append(prev,count,next);wrap.append(img,cap,controls);if(!modal.open)modal.showModal()}
