let pets=0;const cat=document.querySelector('#pixelcat');cat.onclick=()=>{pets++;cat.classList.remove('cat-petted');requestAnimationFrame(()=>cat.classList.add('cat-petted'));document.querySelector('#cat-status').textContent=['mrrp. hello, human.','purr.exe is running','one more pet, please','you may pass, builder'][pets%4];cat.querySelector('.catface').textContent=pets%2?'/\\_/\\\n( -.- )\n > ^ <':'/\\_/\\\n( o.o )\n > ^ <'};
