const shell=document.querySelector('#shell-output'),input=document.querySelector('#shell-input');function printShell(text){const line=document.createElement('p');line.textContent=text;shell.append(line);while(shell.children.length>35)shell.firstElementChild.remove();shell.scrollTop=shell.scrollHeight}function command(value){const cmd=value.trim().toLowerCase();if(!cmd)return;printShell('yos ~ $ '+value.trim());const responses={help:'help · projects · about · stack · contact · theme · cat · clear\nTip: try secret.',projects:'LeadUno / Spread Checker / Pedagogium automation / HoolsOnline / ASCII Cam\nOpening the project shelf…',about:'Yaroslav / yosStudent\nProduct builder. Backend + AI integrations.\nFinal semester: Informatyka / Systemy chmurowe / ZPSB.',stack:'Python, FastAPI, Flask, TypeScript, Node.js, PostgreSQL, OpenAI API, Telegram, Chrome MV3, Linux.',contact:'github.com/yosStudent\nOpen “get in touch” for the contact window.',theme:'The sky is changing. Nothing else has to.',cat:' /\\_/\\\n( o.o )   mrrp.\n > ^ <\nThe deployment supervisor approves.',secret:'You found a quiet corner.\nThere are five tiny stars hiding above the city.'};if(cmd==='clear'){shell.replaceChildren();return}printShell(responses[cmd]||'Unknown command. Try help.');if(cmd==='projects')document.querySelector('#projects').scrollIntoView({behavior:quiet?'instant':'smooth'});if(cmd==='theme')changePalette();if(cmd==='cat')cat.click()}document.querySelector('#shell-form').onsubmit=e=>{e.preventDefault();command(input.value);input.value=''};document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>command(b.dataset.command));
let audio=null,audioTimer=null;const music=document.querySelector('#music');function stopMusic(){if(audioTimer)clearInterval(audioTimer);audioTimer=null;if(audio)audio.close().catch(()=>{});audio=null;music.textContent='♫ play night radio';music.setAttribute('aria-pressed','false')}music.onclick=()=>{if(audio){stopMusic();return}const AC=window.AudioContext||window.webkitAudioContext;if(!AC){music.textContent='audio unavailable in this browser';return}audio=new AC();const out=audio.createGain();out.gain.value=.035;out.connect(audio.destination);const notes=[130.81,196,261.63,164.81,220,196,146.83,174.61];let ni=0;function note(){if(!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=notes[ni++%notes.length];o.connect(g);g.connect(out);const t=audio.currentTime;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.5,t+.08);g.gain.exponentialRampToValueAtTime(.001,t+1.4);o.start(t);o.stop(t+1.5)}note();audioTimer=setInterval(note,750);music.textContent='Ⅱ stop night radio';music.setAttribute('aria-pressed','true')};document.addEventListener('visibilitychange',()=>{if(document.hidden)stopMusic()});
let lastSpark=0;document.addEventListener('pointermove',e=>{if(quiet||e.pointerType!=='mouse'||performance.now()-lastSpark<130)return;lastSpark=performance.now();const dot=document.createElement('span');dot.className='spark';dot.textContent='·';dot.style.left=e.clientX+'px';dot.style.top=e.clientY+'px';document.body.append(dot);setTimeout(()=>dot.remove(),800)});



